import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def _edge_cost(G, s, t):
    c = G[s][t].get("cost")
    return c if c is not None else 0.0


def search_algorithm(src, dsts, G, num_partitions):
    """Best-of-candidates broadcast routing.

    Generates several candidate routing solutions:
      1. Independent per-destination shortest paths (cheap direct routes).
      2. Approximate Steiner tree (multi-source Dijkstra heuristic) that
         maximizes edge sharing to eliminate redundant transfers.
      3. Steiner tree built with a different attach order for diversity.
      4. Full shortest-path tree from src (single Dijkstra, max edge reuse).
      5. Hybrid — Steiner tree with per-destination fallback to direct
         shortest paths when they avoid costly unique tree edges.
    Each candidate is evaluated under the cost model where every distinct
    edge used is paid once per partition; the cheapest candidate is used
    for all partitions, minimizing total broadcast cost.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    def steiner_tree(order_key):
        tree_nodes = {src}
        tree_pred = {}
        remaining = set(dsts)
        while remaining:
            dist, paths = nx.multi_source_dijkstra(h, list(tree_nodes), weight="cost")
            if not all(d in dist for d in remaining):
                return None
            best_dst = min(remaining, key=lambda d: (order_key(d), dist[d]))
            path = paths[best_dst]
            for i in range(len(path) - 1):
                child, parent = path[i + 1], path[i]
                if child not in tree_pred:
                    tree_pred[child] = parent
                tree_nodes.add(child)
            remaining.discard(best_dst)

        def tree_path_to(dst):
            node = dst
            rev = []
            while node != src:
                rev.append((tree_pred[node], node))
                node = tree_pred[node]
            return list(reversed(rev))

        return {dst: tree_path_to(dst) for dst in dsts}

    candidates = []

    # Candidate 1: independent shortest paths
    indep = {}
    ok = True
    for dst in dsts:
        try:
            p = nx.shortest_path(h, src, dst, weight="cost")
        except nx.NetworkXNoPath:
            ok = False
            break
        indep[dst] = [(p[i], p[i + 1]) for i in range(len(p) - 1)]
    if ok:
        candidates.append(indep)

    # Candidates 2 & 3: Steiner trees with different attach orders
    t1 = steiner_tree(lambda d: 0)
    if t1:
        candidates.append(t1)
    t2 = steiner_tree(lambda d: hash(d) % 1000)
    if t2:
        candidates.append(t2)

    # Candidate 4: full shortest-path tree from src (single Dijkstra)
    try:
        _, sp_tree = nx.single_source_dijkstra(h, src, weight="cost")
        spt = {}
        ok = True
        for dst in dsts:
            if dst not in sp_tree:
                ok = False
                break
            p = sp_tree[dst]
            spt[dst] = [(p[i], p[i + 1]) for i in range(len(p) - 1)]
        if ok:
            candidates.append(spt)
    except nx.NetworkXNoPath:
        pass

    # Candidate 5: hybrid — Steiner tree with per-destination fallback
    if t1 and indep:
        hybrid = dict(t1)
        used = set()
        for dst in dsts:
            for e in t1[dst]:
                used.add(e)
        for dst in dsts:
            if dst not in indep:
                continue
            new_edges = set(e for e in indep[dst] if e not in used)
            old_edges = set(e for e in t1[dst] if sum(
                1 for d2 in dsts if e in t1[d2]) == 1)
            new_cost = sum(_edge_cost(G, s, t) for (s, t) in new_edges)
            old_cost = sum(_edge_cost(G, s, t) for (s, t) in old_edges)
            if new_cost < old_cost:
                hybrid[dst] = indep[dst]
                used.update(new_edges)
        candidates.append(hybrid)

    if not candidates:
        return BroadCastTopology(src, dsts, num_partitions)

    def candidate_cost(paths):
        edges = set()
        for dst in dsts:
            for (s, t) in paths[dst]:
                edges.add((s, t))
        return sum(_edge_cost(G, s, t) for (s, t) in edges)

    best = min(candidates, key=candidate_cost)

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    for dst in dsts:
        for (s, t) in best[dst]:
            for j in range(bc_topology.num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, G[s][t]])

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

